verb :moveto(target) rx {
  /* A preallocated artifact stays in the producing block until that block's
     sequenced :deliver moves it. Knowing its ref is not a movement grant. */
  if (location(this) == this.produced_by && caller != this.produced_by) { raise { code: "E_PERM", message: "pending dispenser artifact is producer-controlled", value: this }; }
  if (target != null && isa(target, $space)) {
    let title = this.name;
    if (typeof(title) != "string" || !title) { title = "the note"; }
    let drop_text = title + " disperses in a puff of smoke.";
    if (actor != null && isa(actor, $actor)) { drop_text = actor.name + " drops " + title + ", which disperses in a puff of smoke."; }
    observe_to_space(target, { type: "note_dispersed", source: target, room: target, note: this, actor: actor, text: drop_text, ts: now() });
    recycle(this);
    return target;
  }
  moveto(this, target);
  return target;
}

verb :_queue() r {
  if (caller != this) { raise { code: "E_PERM", message: "queue lookup is dispenser-internal" }; }
  let here = location(this);
  for p in this.projections {
    let ok = false;
    try { ok = valid(p) && isa(p, $dispenser_queue) && location(p) == here && p.source_space == this && p.log_space == here; } except err { ok = false; }
    if (ok) { return p; }
  }
  return null;
}

verb :_require_sequenced() r {
  if (caller != this) { raise { code: "E_PERM", message: "sequencing guard is dispenser-internal" }; }
  let here = location(this);
  if (seq < 1 || here == null || !isa(here, $space) || space != here) { raise { code: "E_INVARG", message: "dispenser mutation requires its containing room's sequenced turn", value: { block: this, log_space: space } }; }
  return here;
}

verb :moveto(target) rx {
  /* A projection is bound to one semantic log. Rehoming an initialized block
     would strand that queue and make a fresh room appear to restart its ids;
     a future migration must name and atomically transfer both authorities. */
  if (this.acts_initialized && target != location(this)) { raise { code: "E_INVARG", message: "initialized dispenser cannot move across log spaces", value: { block: this, from: location(this), to: target } }; }
  return pass(target);
}

verb :_ensure_acts() r {
  if (caller != this) { raise { code: "E_PERM", message: "acts mounting is dispenser-internal" }; }
  let here = this:_require_sequenced();
  let queue = this:_queue();
  let kept = [];
  for p in this.projections {
    let ok = false;
    try { ok = valid(p) && isa(p, $projection) && location(p) == here && p.source_space == this && p.log_space == here; } except err { ok = false; }
    if (ok) { kept = kept + [p]; }
  }
  if (queue == null) {
    queue = create($dispenser_queue, { owner: this.owner, name: "dispenser_queue", location: here });
    queue.source_space = this;
    queue.log_space = here;
    queue.row_cap = 50;
    kept = kept + [queue];
  }
  this.projections = kept;
  let mounted = false;
  for f in this.features { if (f == $acts) { mounted = true; } }
  if (!mounted) {
    this.features = this.features + [$acts];
    this.features_version = this.features_version + 1;
  }
  if (!this.acts_initialized) {
    let next_seq = this.legacy_next_order_seq;
    if (typeof(next_seq) != "number" || next_seq < 1) { next_seq = 1; }
    if (length(this.legacy_pending_orders) > queue.row_cap) { raise { code: "E_QUOTA", message: "legacy dispenser queue exceeds the v1 row cap", value: { max: queue.row_cap, got: length(this.legacy_pending_orders) } }; }
    this:act("dispenser.genesis", { next_order_seq: floor(next_seq) });
    for entry in this.legacy_pending_orders {
      if (typeof(entry) != "map" || typeof(entry["order_id"]) != "string" || !entry["order_id"] || !valid(entry["requester"]) || typeof(entry["request"]) != "string") {
        raise { code: "E_INVARG", message: "invalid legacy dispenser queue row", value: entry };
      }
      if (length(entry["request"]) > 200) { raise { code: "E_QUOTA", message: "legacy dispenser request exceeds the v1 inline cap", value: { order_id: entry["order_id"], max: 200, got: length(entry["request"]) } }; }
      let artifact = create($dispensed_note, { owner: this, name: "pending delivery", location: this });
      artifact.produced_by = this;
      artifact.order_id = entry["order_id"];
      this:act("dispenser.legacy_ordered", { order_id: entry["order_id"], requester: entry["requester"], request: entry["request"], artifact: artifact });
    }
    this.legacy_pending_orders = [];
    this.legacy_last_request_at = {};
    this.legacy_last_order_at = 0;
    this.acts_initialized = true;
  }
  return queue;
}

verb :_seq_ts(entry_seq) r {
  if (caller != this) { raise { code: "E_PERM", message: "log timestamp lookup is dispenser-internal" }; }
  if (typeof(entry_seq) != "number" || entry_seq < 1) { return 0; }
  let here = location(this);
  for e in here:replay(entry_seq, 1) { if (e["seq"] == entry_seq) { return e["ts"]; } }
  return 0;
}

verb :order(request) rxd {
  this:_require_sequenced();
  if (typeof(request) != "string" || !request) { raise { code: "E_INVARG", message: "order requires a non-empty request string", value: request }; }
  let max_chars = this.max_request_chars;
  if (typeof(max_chars) != "number" || max_chars <= 0 || max_chars > 200) { max_chars = 200; }
  if (length(request) > max_chars) { raise { code: "E_INVARG", message: "request exceeds max_request_chars", value: { max: max_chars, got: length(request) } }; }
  let queue = this:_ensure_acts();
  let state = queue:admission_state(actor);
  let max_q = this.max_pending_orders;
  if (typeof(max_q) != "number" || max_q <= 0 || max_q > queue.row_cap) { max_q = queue.row_cap; }
  if (state["pending"] >= max_q) { raise { code: "E_QUEUE_FULL", message: "block has too many pending orders", value: { max: max_q, current: state["pending"] } }; }
  let now_ms = now();
  let cool_s = this.block_cooldown_seconds;
  if (typeof(cool_s) == "number" && cool_s > 0 && state["last_order_seq"] > 0) {
    let last_block = this:_seq_ts(state["last_order_seq"]);
    if (last_block > 0 && (now_ms - last_block) < (cool_s * 1000)) { raise { code: "E_RATE_LIMIT", message: "block-wide cooldown active", value: { retry_in_seconds: cool_s - ((now_ms - last_block) / 1000), scope: "block", block_cooldown_seconds: cool_s } }; }
  }
  let limit_s = this.rate_limit_seconds;
  if (typeof(limit_s) != "number") { limit_s = 60; }
  if (limit_s > 0 && state["requester_last_seq"] > 0) {
    let last_actor = this:_seq_ts(state["requester_last_seq"]);
    if (last_actor > 0 && (now_ms - last_actor) < (limit_s * 1000)) { raise { code: "E_RATE_LIMIT", message: "too many orders from this requester; try again later", value: { retry_in_seconds: limit_s - ((now_ms - last_actor) / 1000), scope: "requester", rate_limit_seconds: limit_s } }; }
  }
  let order_id = "ord_" + to_string(state["next_order_seq"]);
  /* Preallocate the final artifact in this room-anchored turn. The plug later
     fills it through a direct object-authority call, so delivery's sequenced
     message and Act carry only refs, never generated prose. */
  let artifact = create($dispensed_note, { owner: this, name: "pending delivery", location: this });
  artifact.produced_by = this;
  artifact.order_id = order_id;
  this:act("dispenser.ordered", { order_id: order_id, request: request, artifact: artifact });
  let text = this.name + " accepts your order " + order_id + ". Your note will arrive in your inventory when it is ready.";
  tell(actor, text);
  try { tell(this, "order:" + order_id); } except err { }
  return { order_id: order_id, queued: true, text: text, ts: now_ms };
}

verb :prepare_artifact(order_id, name, text, description) rx {
  /* Generated prose belongs on the preallocated artifact, not in a room-log
     message. This write is therefore direct-only; :deliver later records only
     the artifact ref. A fresh-key retry returns the same prepared note. */
  if (seq >= 1) { raise { code: "E_INVARG", message: "artifact preparation must use a direct turn" }; }
  if (actor != this && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "only the block actor (plug) or wizard can prepare", value: actor }; }
  if (typeof(order_id) != "string" || !order_id) { raise { code: "E_INVARG", message: "prepare_artifact requires order_id", value: order_id }; }
  let queue = this:_queue();
  if (queue == null) { return { order_id: order_id, prepared: false, duplicate: false, reason: "unknown" }; }
  let found = queue:lookup(order_id);
  if (found["state"] == "delivered") { return { order_id: order_id, prepared: true, duplicate: true, note: found["note"] }; }
  if (found["state"] != "queued") { return { order_id: order_id, prepared: false, duplicate: found["state"] == "canceled", reason: found["state"] }; }
  let note = found["artifact"];
  if (!valid(note) || !isa(note, $dispensed_note) || note.produced_by != this || note.order_id != order_id || location(note) != this) { raise { code: "E_INVARG", message: "order has no valid preallocated artifact", value: order_id }; }
  if (note.produced_at > 0) { return { order_id: order_id, prepared: true, duplicate: true, note: note }; }
  if (typeof(name) != "string" || !name || length(name) > 256) { raise { code: "E_INVARG", message: "prepare_artifact requires a 1..256 character name", value: name }; }
  if (typeof(text) != "string") { raise { code: "E_INVARG", message: "prepare_artifact requires a text string", value: text }; }
  if (description != null && (typeof(description) != "string" || length(description) > 4096)) { raise { code: "E_INVARG", message: "prepare_artifact description must be null or at most 4096 characters", value: description }; }
  set_object_name(note, name);
  if (typeof(description) == "string" && description) { note.description = description; }
  note:_set_initial_text(text);
  note.produced_at = now();
  return { order_id: order_id, prepared: true, duplicate: false, note: note };
}

verb :deliver(order_id, note) rx {
  this:_require_sequenced();
  if (actor != this && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "only the block actor (plug) or wizard can deliver", value: actor }; }
  if (typeof(order_id) != "string" || !order_id) { raise { code: "E_INVARG", message: "deliver requires order_id", value: order_id }; }
  let queue = this:_ensure_acts();
  let found = queue:lookup(order_id);
  if (found["state"] == "delivered") { return { order_id: order_id, delivered: true, duplicate: true, note: found["note"], text: this.name + " already delivered this order." }; }
  if (found["state"] == "canceled") { return { order_id: order_id, delivered: false, duplicate: true, reason: "canceled" }; }
  if (found["state"] != "queued") { return { order_id: order_id, delivered: false, duplicate: false, reason: "unknown" }; }
  if (note != found["artifact"] || !valid(note) || !isa(note, $dispensed_note) || note.produced_by != this || note.order_id != order_id || note.produced_at < 1 || location(note) != this) { raise { code: "E_INVARG", message: "deliver requires this order's prepared artifact", value: note }; }
  let requester = found["requester"];
  let title = note.name;
  moveto(note, requester);
  this:act("dispenser.delivered", { order_id: order_id, note: note });
  let line = this.name + " delivers a note to your inventory: " + title;
  tell(requester, line);
  return { order_id: order_id, delivered: true, duplicate: false, note: note, text: line };
}

verb :cancel(order_id) rxd {
  this:_require_sequenced();
  if (typeof(order_id) != "string" || !order_id) { raise { code: "E_INVARG", message: "cancel requires order_id", value: order_id }; }
  let queue = this:_ensure_acts();
  let found = queue:lookup(order_id);
  if (found["state"] == "unknown") { return { order_id: order_id, canceled: false, duplicate: false, reason: "unknown" }; }
  if (actor != found["requester"] && actor != this.owner && actor != this && !has_flag(actor, "wizard")) { return { order_id: order_id, canceled: false, duplicate: false, reason: "unknown" }; }
  if (found["state"] == "canceled") { return { order_id: order_id, canceled: true, duplicate: true }; }
  if (found["state"] == "delivered") { return { order_id: order_id, canceled: false, duplicate: true, reason: "delivered" }; }
  let artifact = found["artifact"];
  if (valid(artifact) && location(artifact) == this) { recycle(artifact); }
  this:act("dispenser.canceled", { order_id: order_id });
  return { order_id: order_id, canceled: true, duplicate: false };
}

verb :pending_count() r {
  if (caller != this) { raise { code: "E_PERM", message: "pending count is dispenser-internal" }; }
  if (!this.acts_initialized) { return length(this.legacy_pending_orders); }
  let queue = this:_queue();
  if (queue == null) { return 0; }
  return queue:pending_count();
}

verb :next_pending() rxd {
  if (actor != this && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "only the block actor (plug) or wizard can read pending orders", value: actor }; }
  if (!this.acts_initialized) { if (length(this.legacy_pending_orders) == 0) { return null; } return this.legacy_pending_orders[1]; }
  let queue = this:_queue();
  if (queue == null) { raise { code: "E_INVARG", message: "initialized dispenser has no bound queue projection" }; }
  return queue:next_pending();
}

verb :status(order_id) rxd {
  if (typeof(order_id) != "string" || !order_id) { raise { code: "E_INVARG", message: "status requires order_id", value: order_id }; }
  if (!this.acts_initialized) {
    for item in this.legacy_pending_orders { if (item["order_id"] == order_id) { if (actor != item["requester"] && actor != this && actor != this.owner && !has_flag(actor, "wizard")) { return { state: "unknown", order_id: order_id }; } return { state: "queued", order_id: order_id, ts: item["ts"] }; } }
    return { state: "unknown", order_id: order_id };
  }
  let queue = this:_queue();
  if (queue == null) { return { state: "unknown", order_id: order_id }; }
  let found = queue:lookup(order_id);
  if (found["state"] != "unknown" && actor != found["requester"] && actor != this && actor != this.owner && !has_flag(actor, "wizard")) { return { state: "unknown", order_id: order_id }; }
  return found;
}

verb :get_data(name) rxd {
  if (name in ["projections", "acts_initialized", "legacy_pending_orders", "legacy_next_order_seq", "legacy_last_request_at", "legacy_last_order_at"]) { if (actor != this && actor != this.owner && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "dispenser coordination data is private", value: { property: name, actor: actor } }; } }
  return pass(name);
}

verb :fold(act) r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "projection fold is authority-internal" }; }
  if (act["source"] != this.source_space) { return false; }
  let ty = act["type"];
  let p = act["payload"];
  let rows = this.rows;
  let requesters = this.requester_index;
  let receipts = this.receipts;
  if (ty == "dispenser.genesis") {
    if (!this.genesis_seen) {
      if (p["next_order_seq"] < 1) { raise { code: "E_INVARG", message: "invalid dispenser genesis counter", value: p["next_order_seq"] }; }
      this.next_order_seq = p["next_order_seq"];
      this.genesis_seen = true;
    }
  } else if (ty == "dispenser.legacy_ordered" || ty == "dispenser.ordered") {
    if (!this.genesis_seen) { raise { code: "E_INVARG", message: "dispenser order before genesis" }; }
    let key = p["order_id"];
    if (key in rows || key in receipts) { raise { code: "E_INVARG", message: "duplicate dispenser order id", value: key }; }
    if (length(rows) >= this.row_cap) { raise { code: "E_QUOTA", message: "dispenser queue row cap", value: this.row_cap }; }
    let requester = act["actor"];
    if (ty == "dispenser.legacy_ordered") { requester = p["requester"]; }
    else {
      let expected = "ord_" + to_string(this.next_order_seq);
      if (key != expected) { raise { code: "E_INVARG", message: "dispenser order id is not the projected next id", value: { expected: expected, got: key } }; }
      this.next_order_seq = this.next_order_seq + 1;
      let requester_key = to_string(requester);
      if (!(requester_key in requesters) && length(requesters) >= this.requester_cap) {
        let evict = null;
        let oldest = null;
        for rk in keys(requesters) { let rs = requesters[rk]; if (oldest == null || rs < oldest || (rs == oldest && rk < evict)) { oldest = rs; evict = rk; } }
        let kept_requesters = {};
        for rk, rs in requesters { if (rk != evict) { kept_requesters[rk] = rs; } }
        requesters = kept_requesters;
      }
      requesters[requester_key] = act["seq"];
      this.last_order_seq = act["seq"];
    }
    rows[key] = { order_id: key, requester: requester, request: p["request"], artifact: p["artifact"], ordered_seq: act["seq"], queue_seq: this.next_queue_seq };
    this.next_queue_seq = this.next_queue_seq + 1;
  } else if (ty == "dispenser.delivered" || ty == "dispenser.canceled") {
    let terminal_key = p["order_id"];
    if (!(terminal_key in rows)) {
      if (terminal_key in receipts) { this.at_seq = act["seq"]; return true; }
      raise { code: "E_INVARG", message: "terminal dispenser act for unknown order", value: terminal_key };
    }
    let row = rows[terminal_key];
    if (ty == "dispenser.delivered" && p["note"] != row["artifact"]) { raise { code: "E_INVARG", message: "delivered note is not the order artifact", value: p["note"] }; }
    let kept_rows = {};
    for ok, ov in rows { if (ok != terminal_key) { kept_rows[ok] = ov; } }
    rows = kept_rows;
    if (!(terminal_key in receipts) && length(receipts) >= this.receipt_cap) {
      let receipt_evict = null;
      let receipt_oldest = null;
      for tk in keys(receipts) { let terminal_seq = receipts[tk]["terminal_seq"]; if (receipt_oldest == null || terminal_seq < receipt_oldest || (terminal_seq == receipt_oldest && tk < receipt_evict)) { receipt_oldest = terminal_seq; receipt_evict = tk; } }
      let kept_receipts = {};
      for tk, tv in receipts { if (tk != receipt_evict) { kept_receipts[tk] = tv; } }
      receipts = kept_receipts;
    }
    if (ty == "dispenser.delivered") { receipts[terminal_key] = { state: "delivered", order_id: terminal_key, requester: row["requester"], note: p["note"], terminal_seq: act["seq"] }; }
    else { receipts[terminal_key] = { state: "canceled", order_id: terminal_key, requester: row["requester"], terminal_seq: act["seq"] }; }
  }
  this.rows = rows;
  this.requester_index = requesters;
  this.receipts = receipts;
  this.at_seq = act["seq"];
  return true;
}

verb :admission_state(requester) r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "admission state is dispenser-internal" }; }
  let last = 0;
  let key = to_string(requester);
  if (key in this.requester_index) { last = this.requester_index[key]; }
  return { pending: length(this.rows), next_order_seq: this.next_order_seq, last_order_seq: this.last_order_seq, requester_last_seq: last, at_seq: this.at_seq };
}

verb :lookup(order_id) r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "queue lookup is dispenser-internal" }; }
  if (order_id in this.rows) { let row = this.rows[order_id]; return { state: "queued", order_id: order_id, requester: row["requester"], artifact: row["artifact"], ordered_seq: row["ordered_seq"] }; }
  if (order_id in this.receipts) { return this.receipts[order_id]; }
  return { state: "unknown", order_id: order_id };
}

verb :next_pending() r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "queue read is dispenser-internal" }; }
  let found = null;
  let best = null;
  for k in keys(this.rows) { let row = this.rows[k]; if (best == null || row["queue_seq"] < best) { best = row["queue_seq"]; found = row; } }
  if (found == null) { return null; }
  let ts = 0;
  for e in this.log_space:replay(found["ordered_seq"], 1) { if (e["seq"] == found["ordered_seq"]) { ts = e["ts"]; } }
  return { order_id: found["order_id"], requester: found["requester"], request: found["request"], ts: ts };
}

verb :pending_count() r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "queue count is dispenser-internal" }; }
  return length(this.rows);
}

verb :view(opts) r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "dispenser queue view is internal" }; }
  return { pending: length(this.rows), at_seq: this.at_seq, next_order_seq: this.next_order_seq };
}
